-- Alemiya Academy: all database migrations in one file.
-- GENERATED by "npm run db:bundle". Do not edit; edit the files in supabase/migrations instead.
-- Run this ONCE on a new, empty Supabase project (SQL Editor > New query > paste > Run).
-- Running it twice fails with "already exists", which is safe: nothing is changed.
-- Files included: 20261118000100_reference_tables.sql, 20261118000200_students.sql, 20261118000300_attendance.sql, 20261118000400_results.sql, 20261118000500_fees.sql, 20261118000600_term_records_and_history.sql, 20261118000700_enable_row_level_security.sql, 20261118000800_roles_and_policies.sql, 20261118000900_set_current.sql, 20261118001000_admission_numbers.sql, 20261118001100_student_movements.sql, 20261118001200_save_attendance_week.sql, 20261118001300_attendance_totals.sql, 20261118001400_staff_attendance.sql, 20261118001500_staff_attendance_totals.sql, 20261118001600_save_scores.sql, 20261118001700_save_remarks.sql, 20261118001800_publish_results.sql, 20261118001900_fee_items_history.sql, 20261118002000_record_payment.sql, 20261118002100_fee_balances.sql, 20261118002200_void_payment.sql, 20261118002300_parent_me.sql, 20261118002400_parent_views.sql, 20261118002500_enrolment_turnover.sql, 20261118002600_results_summary.sql, 20261118002700_term_close.sql, 20261118002800_year_end_promotion.sql, 20261118002900_single_score.sql, 20261118003000_notices.sql, 20261118003100_timetable.sql, 20261118003200_lock_function_access.sql

-- ======================================================================
-- 20261118000100_reference_tables.sql
-- ======================================================================
-- T02 / migration 1: school setup tables
-- Every table has created_by and created_at so each record shows who entered it and when.

create table public.settings (
  id uuid primary key default gen_random_uuid(),
  singleton boolean not null default true unique check (singleton),   -- only one row allowed
  school_name text not null default '',
  location text,
  district text,
  region text,
  circuit text,
  logo_url text,
  next_term_opening_date date,
  class_score_max numeric(5,2) not null default 30 check (class_score_max > 0),  -- open question Q1
  exam_score_max numeric(5,2) not null default 70 check (exam_score_max > 0),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

create table public.academic_years (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,                      -- for example 2025/2026
  start_date date not null,
  end_date date not null,
  is_current boolean not null default false,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  check (end_date > start_date)
);
create unique index one_current_academic_year on public.academic_years (is_current) where is_current;

create table public.terms (
  id uuid primary key default gen_random_uuid(),
  academic_year_id uuid not null references public.academic_years (id),
  name text not null check (name in ('Term 1', 'Term 2', 'Term 3')),
  start_date date not null,
  end_date date not null,
  status text not null default 'open' check (status in ('open', 'closed')),
  is_current boolean not null default false,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (academic_year_id, name),
  check (end_date > start_date)
);
create unique index one_current_term on public.terms (is_current) where is_current;

create table public.classes (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,                      -- Creche, Nursery 1, ... JHS 3
  level_order integer not null unique,            -- 1 = Creche ... 14 = JHS 3, used for promotion
  form_teacher_id uuid,                           -- foreign key added after staff exists
  scored boolean not null default true,           -- false = remarks-only report card (rule G8)
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

create table public.subjects (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  type text not null check (type in ('core', 'elective')),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

create table public.class_subjects (
  class_id uuid not null references public.classes (id) on delete cascade,
  subject_id uuid not null references public.subjects (id) on delete cascade,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  primary key (class_id, subject_id)
);

create table public.grade_scale (
  id uuid primary key default gen_random_uuid(),
  min_score numeric(5,2) not null,
  max_score numeric(5,2) not null,
  grade text not null,
  remark text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  check (min_score >= 0 and max_score >= min_score),
  -- score ranges may not overlap (T06 acceptance check)
  exclude using gist (numrange(min_score, max_score, '[]') with &&)
);

-- Links a login to a role. Parents get a row too (role = 'parent').
create table public.profiles (
  id uuid primary key default gen_random_uuid(),
  auth_user_id uuid not null unique references auth.users (id) on delete cascade,
  full_name text not null,
  role text not null check (role in ('admin', 'staff', 'parent')),
  phone text,
  active boolean not null default true,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

-- Simple staff list (no HR fields in version 1)
create table public.staff (
  id uuid primary key default gen_random_uuid(),
  full_name text not null,
  phone text,
  subject_notes text,
  class_id uuid references public.classes (id) on delete set null,
  status text not null default 'active' check (status in ('active', 'inactive')),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

alter table public.classes
  add constraint classes_form_teacher_fk
  foreign key (form_teacher_id) references public.staff (id) on delete set null;

-- ======================================================================
-- 20261118000200_students.sql
-- ======================================================================
-- T02 / migration 2: students, movement history, parent access

create table public.students (
  id uuid primary key default gen_random_uuid(),
  admission_no text not null unique,              -- for example ALM-2026-001 (rule S1), generated in T07
  full_name text not null,
  gender text not null check (gender in ('male', 'female')),
  date_of_birth date,
  class_id uuid references public.classes (id),
  guardian_name text,
  guardian_phone text,
  status text not null default 'active'
    check (status in ('active', 'transferred_out', 'withdrawn', 'graduated')),
  admitted_on date,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);
create index students_class_idx on public.students (class_id);
create index students_status_idx on public.students (status);

-- One row per change of status or class. Basis of enrolment turnover (rules S2 to S4).
create table public.student_movements (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.students (id),
  term_id uuid not null references public.terms (id),
  movement text not null check (movement in
    ('new', 'transfer_in', 'transfer_out', 'withdrawn', 'graduated', 'promoted', 'repeated')),
  moved_on date not null default current_date,
  reason text,
  from_class_id uuid references public.classes (id),
  to_class_id uuid references public.classes (id),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);
create index student_movements_student_idx on public.student_movements (student_id);
create index student_movements_term_idx on public.student_movements (term_id);

-- The access code itself is never stored, only its hash (rule C5, decision D8)
create table public.parent_access (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null unique references public.students (id),
  code_hash text not null,
  auth_user_id uuid unique references auth.users (id) on delete set null,   -- added for T22 login
  last_login timestamptz,
  active boolean not null default true,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

-- ======================================================================
-- 20261118000300_attendance.sql
-- ======================================================================
-- T02 / migration 3: student weekly attendance, staff daily attendance, non-school days

create table public.attendance_weeks (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes (id),
  term_id uuid not null references public.terms (id),
  week_start date not null check (extract(isodow from week_start) = 1),   -- must be a Monday
  school_days integer not null default 5 check (school_days between 0 and 7),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (class_id, week_start)
);

-- Only days absent is stored; days present is calculated (rules A2, A5)
create table public.attendance_entries (
  id uuid primary key default gen_random_uuid(),
  week_id uuid not null references public.attendance_weeks (id),
  student_id uuid not null references public.students (id),
  days_absent integer not null default 0 check (days_absent >= 0),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (week_id, student_id)
);
create index attendance_entries_student_idx on public.attendance_entries (student_id);

-- Rule A4: days absent can never be more than school days
create function public.check_days_absent() returns trigger
language plpgsql as $$
declare
  v_school_days integer;
begin
  select school_days into v_school_days from public.attendance_weeks where id = new.week_id;
  if new.days_absent > v_school_days then
    raise exception 'Days absent (%) cannot be more than school days (%)', new.days_absent, v_school_days;
  end if;
  return new;
end $$;

create trigger attendance_entries_check_days
before insert or update on public.attendance_entries
for each row execute function public.check_days_absent();

-- Lowering school days later must not leave entries above the new limit
create function public.check_school_days() returns trigger
language plpgsql as $$
begin
  if exists (
    select 1 from public.attendance_entries
    where week_id = new.id and days_absent > new.school_days
  ) then
    raise exception 'Some students already have more days absent than %', new.school_days;
  end if;
  return new;
end $$;

create trigger attendance_weeks_check_school_days
before update of school_days on public.attendance_weeks
for each row execute function public.check_school_days();

-- Staff attendance: one row per staff member per school day, Admin only (rules ST1 to ST5)
create table public.staff_attendance (
  id uuid primary key default gen_random_uuid(),
  staff_id uuid not null references public.staff (id),
  attendance_date date not null,
  term_id uuid not null references public.terms (id),
  status text not null default 'present' check (status in ('present', 'absent', 'late', 'on_leave')),
  note text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (staff_id, attendance_date)
);
create index staff_attendance_date_idx on public.staff_attendance (attendance_date);

-- Holidays and closures, left out of staff attendance rates (rule ST4)
create table public.non_school_days (
  id uuid primary key default gen_random_uuid(),
  non_school_date date not null unique,
  term_id uuid references public.terms (id),
  reason text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);

-- ======================================================================
-- 20261118000400_results.sql
-- ======================================================================
-- T02 / migration 4: scores, remarks, publishing

-- Null score = not entered yet. is_absent = student missed the subject (counts as 0, rule G6).
create table public.scores (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.students (id),
  subject_id uuid not null references public.subjects (id),
  term_id uuid not null references public.terms (id),
  class_score numeric(6,2) check (class_score >= 0),
  exam_score numeric(6,2) check (exam_score >= 0),
  is_absent boolean not null default false,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (student_id, subject_id, term_id)
);
create index scores_term_idx on public.scores (term_id);

-- Rule G6: a score cannot be above its maximum (30 and 70 unless changed in settings)
create function public.check_score_limits() returns trigger
language plpgsql as $$
declare
  v_class_max numeric;
  v_exam_max numeric;
begin
  select class_score_max, exam_score_max into v_class_max, v_exam_max from public.settings limit 1;
  v_class_max := coalesce(v_class_max, 30);
  v_exam_max := coalesce(v_exam_max, 70);
  if new.class_score > v_class_max then
    raise exception 'Class score cannot be more than %', v_class_max;
  end if;
  if new.exam_score > v_exam_max then
    raise exception 'Exam score cannot be more than %', v_exam_max;
  end if;
  return new;
end $$;

create trigger scores_check_limits
before insert or update on public.scores
for each row execute function public.check_score_limits();

create table public.report_remarks (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.students (id),
  term_id uuid not null references public.terms (id),
  teacher_remark text,
  head_remark text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (student_id, term_id)
);

-- A row here means the class's results are published to parents (rule C3)
create table public.results_publish (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes (id),
  term_id uuid not null references public.terms (id),
  published_at timestamptz not null default now(),
  published_by uuid references auth.users default auth.uid(),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  unique (class_id, term_id)
);

-- ======================================================================
-- 20261118000500_fees.sql
-- ======================================================================
-- T02 / migration 5: fee items and cash payments

create table public.fee_items (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references public.classes (id),
  term_id uuid not null references public.terms (id),
  name text not null,
  amount numeric(12,2) not null check (amount >= 0),
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);
create index fee_items_class_term_idx on public.fee_items (class_id, term_id);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.students (id),
  term_id uuid not null references public.terms (id),
  amount numeric(12,2) not null check (amount > 0),
  paid_on date not null default current_date,
  receipt_no text not null unique,                -- for example R-2026-0001, generated in T18
  received_by uuid references auth.users default auth.uid(),
  note text,
  status text not null default 'valid' check (status in ('valid', 'void')),
  void_reason text,
  voided_by uuid references auth.users,
  voided_at timestamptz,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now(),
  check (status = 'valid' or (void_reason is not null and length(trim(void_reason)) > 0))
);
create index payments_student_idx on public.payments (student_id);
create index payments_paid_on_idx on public.payments (paid_on);

-- Rule F6: a payment is never edited or deleted, only voided with a reason
create function public.protect_payments() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Payments cannot be deleted. Void the payment instead.';
  end if;
  if old.status = 'void' then
    raise exception 'A voided payment cannot be changed.';
  end if;
  if (new.student_id, new.term_id, new.amount, new.paid_on, new.receipt_no, new.received_by, new.note)
     is distinct from
     (old.student_id, old.term_id, old.amount, old.paid_on, old.receipt_no, old.received_by, old.note) then
    raise exception 'A payment cannot be changed. Void it and record a new one.';
  end if;
  return new;
end $$;

create trigger payments_protect
before update or delete on public.payments
for each row execute function public.protect_payments();

-- ======================================================================
-- 20261118000600_term_records_and_history.sql
-- ======================================================================
-- T02 / migration 6: term snapshots, history of corrections, no-delete protection

-- Written when a term is closed (rule S5). A reopened and re-closed term gets a new row.
create table public.term_snapshots (
  id uuid primary key default gen_random_uuid(),
  term_id uuid not null references public.terms (id),
  data jsonb not null,
  closed_by uuid references auth.users default auth.uid(),
  closed_at timestamptz not null default now(),
  reopened_reason text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);
create index term_snapshots_term_idx on public.term_snapshots (term_id);

-- Earlier values of any corrected record (rules A8, ST3)
create table public.history (
  id uuid primary key default gen_random_uuid(),
  table_name text not null,
  record_id uuid not null,
  old_values jsonb not null,
  changed_by uuid references auth.users default auth.uid(),
  changed_at timestamptz not null default now()
);
create index history_record_idx on public.history (table_name, record_id);

create function public.log_history() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.history (table_name, record_id, old_values, changed_by)
  values (tg_table_name, old.id, to_jsonb(old), auth.uid());
  return new;
end $$;

create trigger students_history after update on public.students
  for each row execute function public.log_history();
create trigger staff_history after update on public.staff
  for each row execute function public.log_history();
create trigger attendance_weeks_history after update on public.attendance_weeks
  for each row execute function public.log_history();
create trigger attendance_entries_history after update on public.attendance_entries
  for each row execute function public.log_history();
create trigger staff_attendance_history after update on public.staff_attendance
  for each row execute function public.log_history();
create trigger scores_history after update on public.scores
  for each row execute function public.log_history();
create trigger report_remarks_history after update on public.report_remarks
  for each row execute function public.log_history();
create trigger fee_items_history after update on public.fee_items
  for each row execute function public.log_history();

-- Decision D9: records are never deleted. Corrections are made by editing (history keeps the old
-- values) or by voiding. Payments have their own protection in migration 5.
create function public.block_delete() returns trigger
language plpgsql as $$
begin
  raise exception 'Records in % cannot be deleted.', tg_table_name;
end $$;

create trigger students_no_delete before delete on public.students
  for each row execute function public.block_delete();
create trigger student_movements_no_delete before delete on public.student_movements
  for each row execute function public.block_delete();
create trigger attendance_weeks_no_delete before delete on public.attendance_weeks
  for each row execute function public.block_delete();
create trigger attendance_entries_no_delete before delete on public.attendance_entries
  for each row execute function public.block_delete();
create trigger staff_attendance_no_delete before delete on public.staff_attendance
  for each row execute function public.block_delete();
create trigger scores_no_delete before delete on public.scores
  for each row execute function public.block_delete();
create trigger term_snapshots_no_delete before delete on public.term_snapshots
  for each row execute function public.block_delete();
create trigger history_no_delete before delete on public.history
  for each row execute function public.block_delete();

-- ======================================================================
-- 20261118000700_enable_row_level_security.sql
-- ======================================================================
-- T02 / migration 7: lock every table.
-- Row-level security is switched on with NO policies, so the browser (anon and logged-in users)
-- can read and write nothing until T03 adds the role policies. Nothing is exposed by accident.

alter table public.settings enable row level security;
alter table public.academic_years enable row level security;
alter table public.terms enable row level security;
alter table public.classes enable row level security;
alter table public.subjects enable row level security;
alter table public.class_subjects enable row level security;
alter table public.grade_scale enable row level security;
alter table public.profiles enable row level security;
alter table public.staff enable row level security;
alter table public.students enable row level security;
alter table public.student_movements enable row level security;
alter table public.parent_access enable row level security;
alter table public.attendance_weeks enable row level security;
alter table public.attendance_entries enable row level security;
alter table public.staff_attendance enable row level security;
alter table public.non_school_days enable row level security;
alter table public.scores enable row level security;
alter table public.report_remarks enable row level security;
alter table public.results_publish enable row level security;
alter table public.fee_items enable row level security;
alter table public.payments enable row level security;
alter table public.term_snapshots enable row level security;
alter table public.history enable row level security;

-- ======================================================================
-- 20261118000800_roles_and_policies.sql
-- ======================================================================
-- T03 / migration 8: who can do what (decision D1 to D13, roles table in section 5 of the plan).
-- Roles live in public.profiles. A logged-in user with NO active profile can do nothing,
-- so even if public sign-up were left on by mistake, a stranger sees no data.
-- Parent policies are added later in T22.

alter table public.profiles add column email text;     -- shown on the Users screen

-- The caller's role: 'admin', 'staff', 'parent', or null (no profile or inactive).
-- security definer lets it read profiles without being blocked by profiles' own rules.
create function public.app_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where auth_user_id = auth.uid() and active
$$;

revoke all on function public.app_role() from public;
grant execute on function public.app_role() to authenticated;

-- ---------------------------------------------------------------------------
-- Admin and Staff can read these tables. Only Admin can add, change or remove rows.
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'settings', 'academic_years', 'terms', 'classes', 'subjects', 'class_subjects',
    'grade_scale', 'staff', 'fee_items', 'results_publish', 'non_school_days', 'term_snapshots'
  ] loop
    execute format(
      'create policy %I on public.%I for select to authenticated using (public.app_role() in (''admin'', ''staff''))',
      t || '_read', t);
    execute format(
      'create policy %I on public.%I for all to authenticated using (public.app_role() = ''admin'') with check (public.app_role() = ''admin'')',
      t || '_admin_write', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Students: Staff can add a new student (status active) but not edit one. Admin can do both.
-- ---------------------------------------------------------------------------
create policy students_read on public.students for select to authenticated
  using (public.app_role() in ('admin', 'staff'));
create policy students_insert on public.students for insert to authenticated
  with check (public.app_role() = 'admin' or (public.app_role() = 'staff' and status = 'active'));
create policy students_admin_update on public.students for update to authenticated
  using (public.app_role() = 'admin') with check (public.app_role() = 'admin');

-- Movement history: Staff can only record a new admission. Admin can record any movement.
create policy student_movements_read on public.student_movements for select to authenticated
  using (public.app_role() in ('admin', 'staff'));
create policy student_movements_insert on public.student_movements for insert to authenticated
  with check (public.app_role() = 'admin' or (public.app_role() = 'staff' and movement = 'new'));

-- ---------------------------------------------------------------------------
-- Day-to-day entry: Staff and Admin can add and save again (history keeps earlier values)
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array['attendance_weeks', 'attendance_entries', 'scores', 'report_remarks'] loop
    execute format(
      'create policy %I on public.%I for select to authenticated using (public.app_role() in (''admin'', ''staff''))',
      t || '_read', t);
    execute format(
      'create policy %I on public.%I for insert to authenticated with check (public.app_role() in (''admin'', ''staff''))',
      t || '_insert', t);
    execute format(
      'create policy %I on public.%I for update to authenticated using (public.app_role() in (''admin'', ''staff'')) with check (public.app_role() in (''admin'', ''staff''))',
      t || '_update', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Payments: Staff and Admin can record a payment under their own name; only Admin can void.
-- ---------------------------------------------------------------------------
create policy payments_read on public.payments for select to authenticated
  using (public.app_role() in ('admin', 'staff'));
create policy payments_insert on public.payments for insert to authenticated
  with check (
    public.app_role() in ('admin', 'staff')
    and status = 'valid'
    and received_by = auth.uid()
  );
create policy payments_admin_void on public.payments for update to authenticated
  using (public.app_role() = 'admin') with check (public.app_role() = 'admin');

-- ---------------------------------------------------------------------------
-- Admin only: staff attendance, parent access codes, history of corrections
-- ---------------------------------------------------------------------------
create policy staff_attendance_admin on public.staff_attendance for all to authenticated
  using (public.app_role() = 'admin') with check (public.app_role() = 'admin');

create policy parent_access_admin on public.parent_access for all to authenticated
  using (public.app_role() = 'admin') with check (public.app_role() = 'admin');

create policy history_admin_read on public.history for select to authenticated
  using (public.app_role() = 'admin');

-- ---------------------------------------------------------------------------
-- Profiles: everyone reads their own row; Admin reads all. Nobody writes from the browser:
-- users are created and changed only by the manage-users server function (service key).
-- ---------------------------------------------------------------------------
create policy profiles_read on public.profiles for select to authenticated
  using (auth_user_id = auth.uid() or public.app_role() = 'admin');

-- ======================================================================
-- 20261118000900_set_current.sql
-- ======================================================================
-- T05: switch the current term (and its academic year) in one step.
-- The unique indexes allow only one current row, so the old one must be cleared first.
-- Runs with the caller's own rights (security invoker), so only Admin can use it.

create or replace function public.set_current_term(p_term_id uuid)
returns void
language plpgsql
security invoker
as $$
declare
  v_year uuid;
begin
  select academic_year_id into v_year from public.terms where id = p_term_id;
  if v_year is null then
    raise exception 'Term not found';
  end if;

  update public.terms set is_current = false where is_current and id <> p_term_id;
  update public.academic_years set is_current = false where is_current and id <> v_year;
  update public.academic_years set is_current = true where id = v_year;
  update public.terms set is_current = true where id = p_term_id;

  if not exists (select 1 from public.terms where id = p_term_id and is_current) then
    raise exception 'Only the Admin can change the current term';
  end if;
end;
$$;

grant execute on function public.set_current_term(uuid) to authenticated;

-- ======================================================================
-- 20261118001000_admission_numbers.sql
-- ======================================================================
-- T07: automatic admission numbers (rule S1) and the "new admission" movement record.
-- Format ALM-<year>-<number>, for example ALM-2026-001. The number counts up within the year
-- of admission. A lock makes sure two people adding students at the same moment never get the same number.

create function public.assign_admission_no() returns trigger
language plpgsql as $$
declare
  v_year text;
  v_next integer;
begin
  if new.admission_no is not null and btrim(new.admission_no) <> '' then
    return new;                       -- Admin typed one in (for example for an old student)
  end if;
  new.admitted_on := coalesce(new.admitted_on, current_date);
  v_year := to_char(new.admitted_on, 'YYYY');
  perform pg_advisory_xact_lock(hashtext('admission_no_' || v_year));
  select coalesce(max(substring(admission_no from '^ALM-' || v_year || '-(\d+)$')::integer), 0) + 1
    into v_next
    from public.students
   where admission_no ~ ('^ALM-' || v_year || '-\d+$');
  new.admission_no := 'ALM-' || v_year || '-' || lpad(v_next::text, 3, '0');
  return new;
end $$;

create trigger students_admission_no before insert on public.students
  for each row execute function public.assign_admission_no();

-- Every new student gets a "new" movement in the current term (basis of enrolment turnover, rule S2).
-- Skipped when no term is marked current yet.
create function public.record_new_admission() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_term uuid;
begin
  select id into v_term from public.terms where is_current limit 1;
  if v_term is not null then
    insert into public.student_movements (student_id, term_id, movement, moved_on, to_class_id, created_by)
    values (new.id, v_term, 'new', coalesce(new.admitted_on, current_date), new.class_id, auth.uid());
  end if;
  return new;
end $$;

create trigger students_new_admission after insert on public.students
  for each row execute function public.record_new_admission();

-- ======================================================================
-- 20261118001100_student_movements.sql
-- ======================================================================
-- T09: moving a student out (transfer, withdrawal, graduation) or bringing one back, with date and reason.
-- Status change and history record are saved together, so they can never disagree.

-- How a new student joined: a new admission or a transfer in from another school (rule S3).
alter table public.students
  add column joined_as text not null default 'new' check (joined_as in ('new', 'transfer_in'));

create or replace function public.record_new_admission() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_term uuid;
begin
  select id into v_term from public.terms where is_current limit 1;
  if v_term is not null then
    insert into public.student_movements (student_id, term_id, movement, moved_on, to_class_id, created_by)
    values (new.id, v_term, new.joined_as, coalesce(new.admitted_on, current_date), new.class_id, auth.uid());
  end if;
  return new;
end $$;

-- Runs with the caller's own rights, so only the Admin can change a student's status.
create function public.record_movement(
  p_student uuid, p_movement text, p_moved_on date, p_reason text
) returns void
language plpgsql security invoker as $$
declare
  v_status text;
  v_class uuid;
  v_term uuid;
  v_new_status text;
  v_rows integer;
begin
  select status, class_id into v_status, v_class from public.students where id = p_student;
  if not found then
    raise exception 'Student not found';
  end if;

  if p_movement in ('transfer_out', 'withdrawn', 'graduated') then
    if v_status <> 'active' then
      raise exception 'Only an active student can be moved out';
    end if;
    v_new_status := case p_movement
      when 'transfer_out' then 'transferred_out'
      when 'withdrawn' then 'withdrawn'
      else 'graduated' end;
  elsif p_movement = 'transfer_in' then
    if v_status = 'active' then
      raise exception 'This student is already active';
    end if;
    v_new_status := 'active';
  else
    raise exception 'Unknown movement';
  end if;

  if p_moved_on is null or p_moved_on > current_date then
    raise exception 'The date cannot be in the future';
  end if;
  if p_movement <> 'graduated' and btrim(coalesce(p_reason, '')) = '' then
    raise exception 'Give a reason';
  end if;

  select id into v_term from public.terms where is_current limit 1;
  if v_term is null then
    raise exception 'Set the current term first';
  end if;

  update public.students set status = v_new_status where id = p_student;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'Only the Admin can change a student status';
  end if;

  insert into public.student_movements (student_id, term_id, movement, moved_on, reason, from_class_id, to_class_id)
  values (
    p_student, v_term, p_movement, p_moved_on, nullif(btrim(p_reason), ''),
    case when p_movement = 'transfer_in' then null else v_class end,
    case when p_movement = 'transfer_in' then v_class else null end
  );
end $$;

grant execute on function public.record_movement(uuid, text, date, text) to authenticated;

-- ======================================================================
-- 20261118001200_save_attendance_week.sql
-- ======================================================================
-- T10: save one class's attendance for one week in a single step (rules A1 to A5, A8).
-- p_entries is a list like [{"student_id": "...", "days_absent": 2}]. Students left out are treated as 0 absences.
-- Runs with the caller's own rights, so the access rules for Staff and Admin still apply.
-- Saving again corrects the week; the history trigger keeps the old values, and only rows that really changed are touched.

create function public.save_attendance_week(
  p_class uuid, p_week_start date, p_school_days integer, p_entries jsonb
) returns uuid
language plpgsql security invoker as $$
declare
  v_term uuid;
  v_term_status text;
  v_week uuid;
  v_entry jsonb;
  v_days integer;
begin
  if extract(isodow from p_week_start) <> 1 then
    raise exception 'The week must start on a Monday';
  end if;
  if p_school_days is null or p_school_days < 0 or p_school_days > 7 then
    raise exception 'School days must be between 0 and 7';
  end if;

  -- the term this week belongs to (judged by the Friday)
  select id, status into v_term, v_term_status
    from public.terms
   where p_week_start + 4 between start_date and end_date
   limit 1;
  if v_term is null then
    raise exception 'This week is not inside any term. Check Setup, Academic years and terms';
  end if;
  if v_term_status = 'closed' then
    raise exception 'This term is closed';
  end if;

  -- creating the week row first; if it exists only the school days may change
  insert into public.attendance_weeks (class_id, term_id, week_start, school_days)
  values (p_class, v_term, p_week_start, p_school_days)
  on conflict (class_id, week_start) do update
    set school_days = excluded.school_days
    where public.attendance_weeks.school_days is distinct from excluded.school_days
  returning id into v_week;
  if v_week is null then
    select id into v_week from public.attendance_weeks where class_id = p_class and week_start = p_week_start;
  end if;

  for v_entry in select * from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) loop
    v_days := coalesce((v_entry ->> 'days_absent')::integer, 0);
    if not exists (select 1 from public.students where id = (v_entry ->> 'student_id')::uuid and class_id = p_class) then
      raise exception 'A student in the list is not in this class';
    end if;
    insert into public.attendance_entries (week_id, student_id, days_absent)
    values (v_week, (v_entry ->> 'student_id')::uuid, v_days)
    on conflict (week_id, student_id) do update
      set days_absent = excluded.days_absent
      where public.attendance_entries.days_absent is distinct from excluded.days_absent;
  end loop;

  return v_week;
end $$;

grant execute on function public.save_attendance_week(uuid, date, integer, jsonb) to authenticated;

-- ======================================================================
-- 20261118001300_attendance_totals.sql
-- ======================================================================
-- T11: attendance totals per student for one term (rules A5 to A7).
-- Only weeks that were saved are counted, so unrecorded weeks never lower a rate (rule A6).
-- A student only counts for weeks where they have an entry (someone who joined later is not marked absent for earlier weeks).
-- Runs with the caller's rights: Admin and Staff can read attendance.

create function public.attendance_term_totals(p_term uuid)
returns table (class_id uuid, student_id uuid, weeks bigint, school_days bigint, days_absent bigint)
language sql stable security invoker as $$
  select w.class_id, e.student_id, count(*), sum(w.school_days), sum(e.days_absent)
    from public.attendance_entries e
    join public.attendance_weeks w on w.id = e.week_id
   where w.term_id = p_term
   group by w.class_id, e.student_id
$$;

grant execute on function public.attendance_term_totals(uuid) to authenticated;

-- ======================================================================
-- 20261118001400_staff_attendance.sql
-- ======================================================================
-- T34: daily staff attendance by the Admin (rules ST1 to ST5).
-- Runs with the caller's rights: the access rules already limit staff_attendance and non_school_days to the Admin.
-- Saving again corrects the day; only rows that really changed are touched, so history keeps just the real corrections.

create function public.save_staff_attendance(p_date date, p_entries jsonb)
returns integer
language plpgsql security invoker as $$
declare
  v_term uuid;
  v_term_status text;
  v_entry jsonb;
  v_status text;
  v_staff uuid;
  v_count integer := 0;
begin
  if p_date is null or p_date > current_date then
    raise exception 'The date cannot be in the future';
  end if;
  if exists (select 1 from public.non_school_days where non_school_date = p_date) then
    raise exception 'This day is marked as a non-school day';
  end if;
  select id, status into v_term, v_term_status from public.terms where p_date between start_date and end_date limit 1;
  if v_term is null then
    raise exception 'This date is not inside any term. Check Setup, Academic years and terms';
  end if;
  if v_term_status = 'closed' then
    raise exception 'This term is closed';
  end if;

  for v_entry in select * from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) loop
    v_staff := (v_entry ->> 'staff_id')::uuid;
    v_status := coalesce(v_entry ->> 'status', 'present');
    if v_status not in ('present', 'absent', 'late', 'on_leave') then
      raise exception 'Unknown attendance status %', v_status;
    end if;
    if not exists (select 1 from public.staff where id = v_staff) then
      raise exception 'A person in the list is not on the staff list';
    end if;
    insert into public.staff_attendance (staff_id, attendance_date, term_id, status, note)
    values (v_staff, p_date, v_term, v_status, nullif(btrim(coalesce(v_entry ->> 'note', '')), ''))
    on conflict (staff_id, attendance_date) do update
      set status = excluded.status, note = excluded.note
      where (public.staff_attendance.status, public.staff_attendance.note) is distinct from (excluded.status, excluded.note);
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

-- Marks a holiday or closure for everyone (rule ST4). Refused if attendance was already saved that day.
create function public.set_non_school_day(p_date date, p_reason text)
returns void
language plpgsql security invoker as $$
declare
  v_term uuid;
  v_rows integer;
begin
  if exists (select 1 from public.staff_attendance where attendance_date = p_date) then
    raise exception 'Attendance was already saved for this day. It cannot be a non-school day';
  end if;
  select id into v_term from public.terms where p_date between start_date and end_date limit 1;
  insert into public.non_school_days (non_school_date, term_id, reason)
  values (p_date, v_term, nullif(btrim(coalesce(p_reason, '')), ''))
  on conflict (non_school_date) do update set reason = excluded.reason;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'Only the Admin can mark a non-school day';
  end if;
end $$;

grant execute on function public.save_staff_attendance(date, jsonb) to authenticated;
grant execute on function public.set_non_school_day(date, text) to authenticated;

-- ======================================================================
-- 20261118001500_staff_attendance_totals.sql
-- ======================================================================
-- T35: staff attendance counts per person for one term (rules ST4 to ST6).
-- Counts only saved days. Days marked as non-school days are left out.
-- Admin only, because the staff_attendance table is Admin only.

create function public.staff_attendance_totals(p_term uuid)
returns table (staff_id uuid, present bigint, late bigint, absent bigint, on_leave bigint)
language sql stable security invoker as $$
  select a.staff_id,
         count(*) filter (where a.status = 'present'),
         count(*) filter (where a.status = 'late'),
         count(*) filter (where a.status = 'absent'),
         count(*) filter (where a.status = 'on_leave')
    from public.staff_attendance a
   where a.term_id = p_term
     and not exists (select 1 from public.non_school_days n where n.non_school_date = a.attendance_date)
   group by a.staff_id
$$;

grant execute on function public.staff_attendance_totals(uuid) to authenticated;

-- ======================================================================
-- 20261118001600_save_scores.sql
-- ======================================================================
-- T12: save one class's scores for one subject and term in a single step (rules G1, G6).
-- p_rows is a list like [{"student_id": "...", "class_score": 24, "exam_score": 51.5, "is_absent": false}].
-- A blank score is sent as null (not entered yet). An absent student has both scores cleared: it counts as 0 (rule G6).
-- Runs with the caller's rights. The score limit trigger from migration 4 still applies to every row.
-- Saving again corrects the scores; only rows that really changed are touched, so history keeps just the real corrections.

create function public.save_scores(p_class uuid, p_subject uuid, p_term uuid, p_rows jsonb)
returns integer
language plpgsql security invoker as $$
declare
  v_status text;
  v_row jsonb;
  v_student uuid;
  v_class numeric;
  v_exam numeric;
  v_absent boolean;
  v_count integer := 0;
begin
  select status into v_status from public.terms where id = p_term;
  if v_status is null then
    raise exception 'Term not found';
  end if;
  if v_status = 'closed' then
    raise exception 'This term is closed';
  end if;
  if not exists (select 1 from public.class_subjects where class_id = p_class and subject_id = p_subject) then
    raise exception 'This subject is not taught in this class. Check Setup, Classes';
  end if;
  if exists (select 1 from public.results_publish where class_id = p_class and term_id = p_term) then
    raise exception 'Results for this class are already published. Ask the Admin before changing scores';
  end if;

  for v_row in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    v_student := (v_row ->> 'student_id')::uuid;
    v_absent := coalesce((v_row ->> 'is_absent')::boolean, false);
    v_class := case when v_absent then null else nullif(v_row ->> 'class_score', '')::numeric end;
    v_exam := case when v_absent then null else nullif(v_row ->> 'exam_score', '')::numeric end;

    if not exists (select 1 from public.students where id = v_student and class_id = p_class) then
      raise exception 'A student in the list is not in this class';
    end if;

    if v_class is null and v_exam is null and not v_absent
       and not exists (select 1 from public.scores where student_id = v_student and subject_id = p_subject and term_id = p_term) then
      continue;   -- nothing entered and nothing saved before: no row needed
    end if;

    insert into public.scores (student_id, subject_id, term_id, class_score, exam_score, is_absent)
    values (v_student, p_subject, p_term, v_class, v_exam, v_absent)
    on conflict (student_id, subject_id, term_id) do update
      set class_score = excluded.class_score, exam_score = excluded.exam_score, is_absent = excluded.is_absent
      where (public.scores.class_score, public.scores.exam_score, public.scores.is_absent)
            is distinct from (excluded.class_score, excluded.exam_score, excluded.is_absent);
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

grant execute on function public.save_scores(uuid, uuid, uuid, jsonb) to authenticated;

-- ======================================================================
-- 20261118001700_save_remarks.sql
-- ======================================================================
-- T14: save a class's teacher and headmaster remarks for one term in one step (rule G9).
-- p_rows is a list like [{"student_id": "...", "teacher_remark": "...", "head_remark": "..."}].
-- Runs with the caller's rights (Staff and Admin may both write remarks). Saving again corrects them;
-- only rows that really changed are touched, so history keeps just the real corrections.

create function public.save_remarks(p_class uuid, p_term uuid, p_rows jsonb)
returns integer
language plpgsql security invoker as $$
declare
  v_status text;
  v_row jsonb;
  v_student uuid;
  v_teacher text;
  v_head text;
  v_count integer := 0;
begin
  select status into v_status from public.terms where id = p_term;
  if v_status is null then
    raise exception 'Term not found';
  end if;
  if v_status = 'closed' then
    raise exception 'This term is closed';
  end if;
  if exists (select 1 from public.results_publish where class_id = p_class and term_id = p_term) then
    raise exception 'Results for this class are already published. Ask the Admin before changing remarks';
  end if;

  for v_row in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    v_student := (v_row ->> 'student_id')::uuid;
    v_teacher := nullif(btrim(coalesce(v_row ->> 'teacher_remark', '')), '');
    v_head := nullif(btrim(coalesce(v_row ->> 'head_remark', '')), '');
    if length(coalesce(v_teacher, '')) > 300 or length(coalesce(v_head, '')) > 300 then
      raise exception 'A remark can have at most 300 characters';
    end if;
    if not exists (select 1 from public.students where id = v_student and class_id = p_class) then
      raise exception 'A student in the list is not in this class';
    end if;
    if v_teacher is null and v_head is null
       and not exists (select 1 from public.report_remarks where student_id = v_student and term_id = p_term) then
      continue;
    end if;
    insert into public.report_remarks (student_id, term_id, teacher_remark, head_remark)
    values (v_student, p_term, v_teacher, v_head)
    on conflict (student_id, term_id) do update
      set teacher_remark = excluded.teacher_remark, head_remark = excluded.head_remark
      where (public.report_remarks.teacher_remark, public.report_remarks.head_remark)
            is distinct from (excluded.teacher_remark, excluded.head_remark);
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

grant execute on function public.save_remarks(uuid, uuid, jsonb) to authenticated;

-- ======================================================================
-- 20261118001800_publish_results.sql
-- ======================================================================
-- T16: publish a class's results for a term, and take them back (rule C3).
-- Publishing is for the Admin only (the results_publish table only lets Admin write).
-- A scored class cannot be published while any active student is missing any score (rule G7).
-- Once published, Staff cannot change scores or remarks (migrations 16 and 17). Unpublishing lets corrections happen;
-- the old publish record is kept in history.

create trigger results_publish_history after delete on public.results_publish
  for each row execute function public.log_history();

create function public.publish_results(p_class uuid, p_term uuid)
returns void
language plpgsql security invoker as $$
declare
  v_status text;
  v_scored boolean;
  v_missing integer;
begin
  if public.app_role() is distinct from 'admin' then
    raise exception 'Only the Admin can publish results';
  end if;
  select status into v_status from public.terms where id = p_term;
  if v_status is null then
    raise exception 'Term not found';
  end if;
  select scored into v_scored from public.classes where id = p_class;
  if v_scored is null then
    raise exception 'Class not found';
  end if;
  if exists (select 1 from public.results_publish where class_id = p_class and term_id = p_term) then
    raise exception 'Results for this class are already published';
  end if;
  if not exists (select 1 from public.students where class_id = p_class and status = 'active') then
    raise exception 'There are no active students in this class';
  end if;

  if v_scored then
    if not exists (select 1 from public.class_subjects where class_id = p_class) then
      raise exception 'No subjects are set for this class. Check Setup, Classes';
    end if;
    select count(*) into v_missing
    from public.students st
    join public.class_subjects cs on cs.class_id = st.class_id
    left join public.scores sc
      on sc.student_id = st.id and sc.subject_id = cs.subject_id and sc.term_id = p_term
    where st.class_id = p_class and st.status = 'active'
      and (sc.id is null or (not sc.is_absent and (sc.class_score is null or sc.exam_score is null)));
    if v_missing > 0 then
      raise exception '% score(s) are still missing. Complete all scores before publishing', v_missing;
    end if;
  end if;

  insert into public.results_publish (class_id, term_id) values (p_class, p_term);
end $$;

create function public.unpublish_results(p_class uuid, p_term uuid)
returns void
language plpgsql security invoker as $$
begin
  if public.app_role() is distinct from 'admin' then
    raise exception 'Only the Admin can unpublish results';
  end if;
  delete from public.results_publish where class_id = p_class and term_id = p_term;
  if not found then
    raise exception 'These results are not published';
  end if;
end $$;

-- ======================================================================
-- 20261118001900_fee_items_history.sql
-- ======================================================================
-- T17: fee items can be deleted by the Admin (a wrong item), but the removed row is kept in history (rule F1).
create trigger fee_items_history_delete after delete on public.fee_items
  for each row execute function public.log_history();

-- ======================================================================
-- 20261118002000_record_payment.sql
-- ======================================================================
-- T18: record a cash payment and give it the next receipt number (rules F3, F4, F6).
-- Receipt numbers look like R-2026-0001 and count up within the year of the payment date.
-- A lock makes sure two people recording at the same moment never get the same number.
-- Numbers of voided payments are never used again (the count looks at every payment, valid or void).
-- Runs with the caller's rights: Staff and Admin may record; the payment is under the caller's own name.

create function public.record_payment(p_student uuid, p_term uuid, p_amount numeric, p_paid_on date, p_note text)
returns table (payment_id uuid, receipt_no text)
language plpgsql security invoker as $$
declare
  v_year text;
  v_next integer;
  v_no text;
  v_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'The amount must be more than zero';
  end if;
  if p_amount > 1000000 or scale(p_amount) > 2 then
    raise exception 'Enter a valid amount in cedis, with at most 2 decimals';
  end if;
  if p_paid_on is null or p_paid_on > current_date then
    raise exception 'The payment date cannot be in the future';
  end if;
  if p_paid_on < current_date - 366 then
    raise exception 'The payment date is too far in the past';
  end if;
  if not exists (select 1 from public.terms where id = p_term) then
    raise exception 'Term not found';
  end if;
  if not exists (select 1 from public.students where id = p_student and status = 'active') then
    raise exception 'Student not found, or not an active student';
  end if;
  if length(coalesce(p_note, '')) > 200 then
    raise exception 'The note can have at most 200 characters';
  end if;

  v_year := to_char(p_paid_on, 'YYYY');
  perform pg_advisory_xact_lock(hashtext('receipt_no_' || v_year));
  select coalesce(max(substring(p.receipt_no from '^R-' || v_year || '-(\d+)$')::integer), 0) + 1
    into v_next
    from public.payments p
   where p.receipt_no ~ ('^R-' || v_year || '-\d+$');
  v_no := 'R-' || v_year || '-' || lpad(v_next::text, 4, '0');

  insert into public.payments (student_id, term_id, amount, paid_on, receipt_no, received_by, note)
  values (p_student, p_term, p_amount, p_paid_on, v_no, auth.uid(), nullif(btrim(coalesce(p_note, '')), ''))
  returning id into v_id;

  return query select v_id, v_no;
end $$;

-- ======================================================================
-- 20261118002100_fee_balances.sql
-- ======================================================================
-- T19: what each active student owes, has paid, and still owes for a term, plus arrears from earlier terms.
-- owed = total of the fee items set for the student's current class and that term (rule F2).
-- paid = valid payments only; voided payments are ignored (rule F6).
-- arrears = the same sum (owed minus paid) over every term that started before this one, using the student's
--   current class for the fees. A negative number means the student has paid ahead.
-- Totals are worked out here so a big school never hits the 1000-row limit on the phone.
-- Runs with the caller's rights (Staff and Admin may both read fees and payments).

create function public.fee_balances(p_term uuid, p_class uuid default null)
returns table (student_id uuid, admission_no text, full_name text, class_id uuid, owed numeric, paid numeric, balance numeric, arrears numeric)
language sql stable security invoker as $$
  with this_term as (select start_date from public.terms where id = p_term),
  fees as (select fi.class_id, fi.term_id, sum(fi.amount) as total from public.fee_items fi group by fi.class_id, fi.term_id),
  pay as (select py.student_id, py.term_id, sum(py.amount) as total from public.payments py where py.status = 'valid' group by py.student_id, py.term_id)
  select s.id, s.admission_no, s.full_name, s.class_id,
         coalesce(f.total, 0), coalesce(p.total, 0), coalesce(f.total, 0) - coalesce(p.total, 0),
         coalesce((
           select sum(coalesce(f2.total, 0) - coalesce(p2.total, 0))
             from public.terms t2
             left join fees f2 on f2.class_id = s.class_id and f2.term_id = t2.id
             left join pay p2 on p2.student_id = s.id and p2.term_id = t2.id
            where t2.start_date < (select start_date from this_term)
         ), 0)
    from public.students s
    left join fees f on f.class_id = s.class_id and f.term_id = p_term
    left join pay p on p.student_id = s.id and p.term_id = p_term
   where s.status = 'active' and (p_class is null or s.class_id = p_class)
   order by s.full_name
$$;

-- ======================================================================
-- 20261118002200_void_payment.sql
-- ======================================================================
-- T20: void a payment that was recorded by mistake (rule F6). Admin only.
-- The payment stays on file with its receipt number, marked void, with the reason, who voided it and when.
-- A voided payment is no longer counted in balances or the daily cash, and cannot be changed again.
-- Runs with the caller's rights: only the Admin may update payments (see policies in migration 8).

create function public.void_payment(p_payment uuid, p_reason text)
returns void
language plpgsql security invoker as $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_status text;
begin
  if public.app_role() is distinct from 'admin' then
    raise exception 'Only the Admin can void a payment';
  end if;
  if length(v_reason) < 3 then
    raise exception 'Give the reason for voiding this payment';
  end if;
  if length(v_reason) > 200 then
    raise exception 'The reason can have at most 200 characters';
  end if;
  select status into v_status from public.payments where id = p_payment;
  if v_status is null then
    raise exception 'Payment not found';
  end if;
  if v_status = 'void' then
    raise exception 'This payment is already voided';
  end if;
  update public.payments
     set status = 'void', void_reason = v_reason, voided_by = auth.uid(), voided_at = now()
   where id = p_payment;
end $$;

-- ======================================================================
-- 20261118002300_parent_me.sql
-- ======================================================================
-- T22: what a logged-in parent is allowed to know about themselves (decision D8, rule C5).
-- Parents have NO direct access to any table: every table policy only lets Admin and Staff in. Parents get a few narrow
-- functions instead. This one says which child the parent's login belongs to. It returns nothing for anyone who is not
-- an active parent of an active student, so the app can tell a parent from a stranger.
-- It also notes the last login (at most once an hour) so the Admin can see who has used their code.

create function public.parent_me()
returns table (student_id uuid, full_name text, admission_no text, class_name text, school_name text)
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return;
  end if;
  update public.parent_access pa
     set last_login = now()
   where pa.auth_user_id = auth.uid() and pa.active
     and (pa.last_login is null or pa.last_login < now() - interval '1 hour');
  return query
    select s.id, s.full_name, s.admission_no, coalesce(c.name, ''), coalesce((select st.school_name from public.settings st limit 1), '')
      from public.parent_access pa
      join public.students s on s.id = pa.student_id
      left join public.classes c on c.id = s.class_id
     where pa.auth_user_id = auth.uid() and pa.active and s.status = 'active';
end $$;

revoke execute on function public.parent_me() from public;
grant execute on function public.parent_me() to authenticated;

-- ======================================================================
-- 20261118002400_parent_views.sql
-- ======================================================================
-- T23: what a parent can see about their own child (rule C3, C5, decision D8).
-- Parents have no direct table access (migration 23). These functions are their only way in. Each one finds the
-- child from the parent's login, and returns nothing or refuses for anyone who is not an active parent.
-- Results are returned only when the Admin has published them for the child's class and term (rule C3).
-- A parent never receives classmates' names or scores: the class is only described by a list of anonymous
-- overall totals, so the screen can work out the child's position.

create function public.parent_child_id() returns uuid
language sql stable security definer set search_path = public as $$
  select s.id from public.parent_access pa join public.students s on s.id = pa.student_id
   where pa.auth_user_id = auth.uid() and pa.active and s.status = 'active'
$$;
revoke execute on function public.parent_child_id() from public;

-- Terms for which this child's class has published results.
create function public.parent_result_terms()
returns table (term_id uuid, term_name text, year_name text)
language sql stable security definer set search_path = public as $$
  select t.id, t.name, y.name
    from public.students s
    join public.results_publish rp on rp.class_id = s.class_id
    join public.terms t on t.id = rp.term_id
    join public.academic_years y on y.id = t.academic_year_id
   where s.id = public.parent_child_id()
   order by t.start_date desc
$$;

create function public.parent_report(p_term uuid)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_student public.students%rowtype;
  v_scored boolean;
  v_class_name text;
  v_term public.terms%rowtype;
  v_year text;
  v_settings public.settings%rowtype;
  v_subjects jsonb;
  v_scores jsonb;
  v_remark jsonb;
  v_att jsonb;
  v_totals jsonb;
  v_size integer;
begin
  select * into v_student from public.students where id = public.parent_child_id();
  if not found then
    raise exception 'Not available';
  end if;
  if not exists (select 1 from public.results_publish where class_id = v_student.class_id and term_id = p_term) then
    raise exception 'These results have not been published yet';
  end if;
  select c.scored, c.name into v_scored, v_class_name from public.classes c where c.id = v_student.class_id;
  select * into v_term from public.terms where id = p_term;
  select name into v_year from public.academic_years where id = v_term.academic_year_id;
  select * into v_settings from public.settings limit 1;

  select coalesce(jsonb_agg(jsonb_build_object('id', sb.id, 'name', sb.name) order by sb.name), '[]'::jsonb) into v_subjects
    from public.class_subjects cs join public.subjects sb on sb.id = cs.subject_id
   where cs.class_id = v_student.class_id and v_scored;

  select coalesce(jsonb_agg(jsonb_build_object('student_id', sc.student_id, 'subject_id', sc.subject_id, 'class_score', sc.class_score, 'exam_score', sc.exam_score, 'is_absent', sc.is_absent)), '[]'::jsonb) into v_scores
    from public.scores sc where sc.student_id = v_student.id and sc.term_id = p_term and v_scored;

  select jsonb_build_object('student_id', r.student_id, 'teacher_remark', r.teacher_remark, 'head_remark', r.head_remark) into v_remark
    from public.report_remarks r where r.student_id = v_student.id and r.term_id = p_term;

  select jsonb_build_object('student_id', v_student.id, 'school_days', sum(w.school_days), 'days_absent', sum(e.days_absent)) into v_att
    from public.attendance_entries e join public.attendance_weeks w on w.id = e.week_id
   where e.student_id = v_student.id and w.term_id = p_term
  having count(*) > 0;

  select count(*) into v_size from public.students where class_id = v_student.class_id and status = 'active';

  -- anonymous overall totals of every active student in the class (class + exam, absent counts 0), for the position
  select coalesce(jsonb_agg(t.total), '[]'::jsonb) into v_totals
    from (
      select coalesce(sum(coalesce(sc.class_score, 0) + coalesce(sc.exam_score, 0)), 0) as total
        from public.students st
        left join public.scores sc on sc.student_id = st.id and sc.term_id = p_term
       where st.class_id = v_student.class_id and st.status = 'active'
       group by st.id
    ) t
   where v_scored;

  return jsonb_build_object(
    'school', jsonb_build_object('name', v_settings.school_name, 'location', v_settings.location, 'district', v_settings.district,
      'region', v_settings.region, 'circuit', v_settings.circuit, 'logo_url', v_settings.logo_url,
      'next_term_opening_date', v_settings.next_term_opening_date, 'class_score_max', v_settings.class_score_max, 'exam_score_max', v_settings.exam_score_max),
    'student', jsonb_build_object('id', v_student.id, 'full_name', v_student.full_name, 'admission_no', v_student.admission_no),
    'class_name', v_class_name, 'term_name', v_term.name, 'year_name', v_year, 'scored', v_scored,
    'scale', (select coalesce(jsonb_agg(jsonb_build_object('min_score', g.min_score, 'max_score', g.max_score, 'grade', g.grade, 'remark', g.remark)), '[]'::jsonb) from public.grade_scale g),
    'subjects', v_subjects, 'scores', v_scores, 'remark', v_remark, 'attendance', v_att,
    'class_totals', v_totals, 'class_size', v_size
  );
end $$;

-- Fees: what the child owes and has paid, term by term (terms that have started), and the valid receipts.
create function public.parent_fees()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_student public.students%rowtype;
  v_terms jsonb;
  v_pay jsonb;
begin
  select * into v_student from public.students where id = public.parent_child_id();
  if not found then
    raise exception 'Not available';
  end if;
  select coalesce(jsonb_agg(q.j order by q.start_date desc), '[]'::jsonb) into v_terms
    from (
      select t.start_date, jsonb_build_object('term_id', t.id, 'term_name', t.name, 'year_name', y.name,
               'owed', coalesce(f.total, 0), 'paid', coalesce(p.total, 0), 'balance', coalesce(f.total, 0) - coalesce(p.total, 0)) as j
        from public.terms t
        join public.academic_years y on y.id = t.academic_year_id
        left join (select term_id, sum(amount) as total from public.fee_items where class_id = v_student.class_id group by term_id) f on f.term_id = t.id
        left join (select term_id, sum(amount) as total from public.payments where student_id = v_student.id and status = 'valid' group by term_id) p on p.term_id = t.id
       where t.start_date <= current_date and (f.total is not null or p.total is not null)
    ) q;
  select coalesce(jsonb_agg(jsonb_build_object('receipt_no', py.receipt_no, 'amount', py.amount, 'paid_on', py.paid_on, 'term_name', t.name) order by py.paid_on desc, py.receipt_no desc), '[]'::jsonb) into v_pay
    from public.payments py join public.terms t on t.id = py.term_id
   where py.student_id = v_student.id and py.status = 'valid';
  return jsonb_build_object('terms', v_terms, 'payments', v_pay);
end $$;

-- Attendance for each term: school days recorded and days absent.
create function public.parent_attendance()
returns table (term_name text, year_name text, school_days bigint, days_absent bigint)
language sql stable security definer set search_path = public as $$
  select t.name, y.name, sum(w.school_days)::bigint, sum(e.days_absent)::bigint
    from public.attendance_entries e
    join public.attendance_weeks w on w.id = e.week_id
    join public.terms t on t.id = w.term_id
    join public.academic_years y on y.id = t.academic_year_id
   where e.student_id = public.parent_child_id()
   group by t.id, t.name, t.start_date, y.name
   order by t.start_date desc
$$;

revoke execute on function public.parent_result_terms() from public;
revoke execute on function public.parent_report(uuid) from public;
revoke execute on function public.parent_fees() from public;
revoke execute on function public.parent_attendance() from public;
grant execute on function public.parent_result_terms() to authenticated;
grant execute on function public.parent_report(uuid) to authenticated;
grant execute on function public.parent_fees() to authenticated;
grant execute on function public.parent_attendance() to authenticated;

-- ======================================================================
-- 20261118002500_enrolment_turnover.sql
-- ======================================================================
-- T24: enrolment turnover per class and gender for one term, and the students behind each number (rules S2 to S4).
-- Every movement is a +1 for the class the student went into and a -1 for the class they left (migration 9 and
-- the new-admission trigger record them with a date). A term's movements are the ones dated from the term's start
-- up to the day before the next term starts (the last term has no end), so holidays between terms belong to the term
-- before them and a term's opening roll always equals the closing roll of the term before.
--   opening = students in the class at the term's start
--   closing = opening + new admissions + transfers in (+ promoted in) - transfers out - withdrawn - graduated (- promoted out)
-- Attrition rate = (transfers out + withdrawn) / opening x 100, worked out on screen.
-- Runs with the caller's rights (the Reports screens are Admin only).

create function public.enrolment_turnover(p_term uuid)
returns table (class_id uuid, gender text, opening bigint, new_admissions bigint, transfers_in bigint, transfers_out bigint,
               withdrawn bigint, graduated bigint, promoted_in bigint, promoted_out bigint, closing bigint)
language sql stable security invoker as $$
  with t as (
    select tm.start_date,
           (select min(t2.start_date) from public.terms t2 where t2.start_date > tm.start_date) as next_start
      from public.terms tm where tm.id = p_term
  ),
  ev as (
    select m.to_class_id as class_id, s.gender, m.moved_on, m.movement, 1 as delta, true as is_in
      from public.student_movements m join public.students s on s.id = m.student_id
     where m.to_class_id is not null
    union all
    select m.from_class_id, s.gender, m.moved_on, m.movement, -1, false
      from public.student_movements m join public.students s on s.id = m.student_id
     where m.from_class_id is not null
  ),
  sums as (
    select e.class_id, e.gender,
           coalesce(sum(e.delta) filter (where e.moved_on < t.start_date), 0) as opening,
           count(*) filter (where in_win and e.is_in and e.movement = 'new') as new_admissions,
           count(*) filter (where in_win and e.is_in and e.movement = 'transfer_in') as transfers_in,
           count(*) filter (where in_win and not e.is_in and e.movement = 'transfer_out') as transfers_out,
           count(*) filter (where in_win and not e.is_in and e.movement = 'withdrawn') as withdrawn,
           count(*) filter (where in_win and not e.is_in and e.movement = 'graduated') as graduated,
           count(*) filter (where in_win and e.is_in and e.movement = 'promoted') as promoted_in,
           count(*) filter (where in_win and not e.is_in and e.movement = 'promoted') as promoted_out,
           coalesce(sum(e.delta) filter (where t.next_start is null or e.moved_on < t.next_start), 0) as closing
      from ev e cross join t
      cross join lateral (select e.moved_on >= t.start_date and (t.next_start is null or e.moved_on < t.next_start) as in_win) w
     group by e.class_id, e.gender
  )
  select c.id, g.gender,
         coalesce(s.opening, 0), coalesce(s.new_admissions, 0), coalesce(s.transfers_in, 0), coalesce(s.transfers_out, 0),
         coalesce(s.withdrawn, 0), coalesce(s.graduated, 0), coalesce(s.promoted_in, 0), coalesce(s.promoted_out, 0), coalesce(s.closing, 0)
    from public.classes c
    cross join (values ('male'), ('female')) as g (gender)
    left join sums s on s.class_id = c.id and s.gender = g.gender
   order by c.level_order, g.gender
$$;

create function public.turnover_students(p_term uuid)
returns table (student_id uuid, full_name text, admission_no text, gender text, class_id uuid, movement text, moved_on date, reason text)
language sql stable security invoker as $$
  with t as (
    select tm.start_date,
           (select min(t2.start_date) from public.terms t2 where t2.start_date > tm.start_date) as next_start
      from public.terms tm where tm.id = p_term
  )
  select s.id, s.full_name, s.admission_no, s.gender, coalesce(m.to_class_id, m.from_class_id), m.movement, m.moved_on, m.reason
    from public.student_movements m
    join public.students s on s.id = m.student_id
    cross join t
   where m.movement in ('new', 'transfer_in', 'transfer_out', 'withdrawn', 'graduated')
     and m.moved_on >= t.start_date and (t.next_start is null or m.moved_on < t.next_start)
   order by m.moved_on, s.full_name
$$;

grant execute on function public.enrolment_turnover(uuid) to authenticated;
grant execute on function public.turnover_students(uuid) to authenticated;

-- ======================================================================
-- 20261118002600_results_summary.sql
-- ======================================================================
-- T25: one row per active student of a scored class for a term, so the Results summary report can add things up
-- without the phone downloading every score (the database returns at most 1000 rows per request).
--   subjects_expected = subjects set for the class
--   subjects_scored   = subjects with a score or marked Absent (rule G6)
--   overall           = total of class + exam scores over the subjects; Absent counts 0 (rule G3)
-- Complete = subjects_scored = subjects_expected and at least one subject (rule G7).
-- Runs with the caller's rights.

create function public.results_summary(p_term uuid)
returns table (student_id uuid, class_id uuid, subjects_expected bigint, subjects_scored bigint, overall numeric)
language sql stable security invoker as $$
  select s.id, s.class_id,
         (select count(*) from public.class_subjects cs where cs.class_id = s.class_id),
         (select count(*) from public.scores sc
           where sc.student_id = s.id and sc.term_id = p_term
             and sc.subject_id in (select cs.subject_id from public.class_subjects cs where cs.class_id = s.class_id)
             and (sc.is_absent or (sc.class_score is not null and sc.exam_score is not null))),
         coalesce((select sum(coalesce(sc.class_score, 0) + coalesce(sc.exam_score, 0)) from public.scores sc
           where sc.student_id = s.id and sc.term_id = p_term
             and sc.subject_id in (select cs.subject_id from public.class_subjects cs where cs.class_id = s.class_id)), 0)
    from public.students s
    join public.classes c on c.id = s.class_id and c.scored
   where s.status = 'active'
$$;

grant execute on function public.results_summary(uuid) to authenticated;

-- ======================================================================
-- 20261118002700_term_close.sql
-- ======================================================================
-- T26: term close (rules S5, S6, S8). Admin only.
--  * term_close_check: missing attendance weeks, incomplete scores and unrecorded staff days, listed before closing.
--  * close_term: saves a read-only snapshot (class lists, student and staff attendance, results, fee balances with
--    arrears, turnover) and marks the term closed. Gaps found by the check stop the close unless the Admin accepts them.
--  * reopen_term: the Admin reopens a closed term with a reason (kept on the snapshot). A term cannot be reopened while
--    a later term is closed.
--  * From the moment a term is closed, the database refuses any new or changed attendance, scores, remarks, staff
--    attendance, fee items and payments for it (even a direct request that skips the screens). Voiding a payment is
--    still allowed for the Admin (permissions table: "void a payment or correct a closed record"). Publishing
--    results is a visibility switch and stays possible.
--  * Unpaid balances carry forward (S6): arrears are always worked out from earlier terms' fees and valid payments
--    (migration 21), and the snapshot freezes them as they stood at close.

create function public.block_closed_term() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_row jsonb;
  v_term uuid;
  v_date date;
begin
  v_row := to_jsonb(case when tg_op = 'DELETE' then old else new end);
  if tg_table_name = 'payments' and tg_op = 'UPDATE' then
    if old.status = 'valid' and new.status = 'void' then
      return new;
    end if;
  end if;
  if tg_table_name = 'attendance_entries' then
    select w.term_id into v_term from public.attendance_weeks w where w.id = (v_row ->> 'week_id')::uuid;
  elsif tg_table_name = 'non_school_days' then
    v_date := (v_row ->> 'non_school_date')::date;
    select t.id into v_term from public.terms t where v_date between t.start_date and t.end_date limit 1;
  else
    v_term := (v_row ->> 'term_id')::uuid;
  end if;
  if v_term is not null and exists (select 1 from public.terms t where t.id = v_term and t.status = 'closed') then
    raise exception 'This term is closed. The Admin can reopen it to make corrections%',
      case when tg_table_name = 'payments' then ', or you can record the payment in the current term' else '' end;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

create trigger scores_closed_term before insert or update or delete on public.scores for each row execute function public.block_closed_term();
create trigger report_remarks_closed_term before insert or update or delete on public.report_remarks for each row execute function public.block_closed_term();
create trigger attendance_weeks_closed_term before insert or update or delete on public.attendance_weeks for each row execute function public.block_closed_term();
create trigger attendance_entries_closed_term before insert or update or delete on public.attendance_entries for each row execute function public.block_closed_term();
create trigger staff_attendance_closed_term before insert or update or delete on public.staff_attendance for each row execute function public.block_closed_term();
create trigger non_school_days_closed_term before insert or update or delete on public.non_school_days for each row execute function public.block_closed_term();
create trigger fee_items_closed_term before insert or update or delete on public.fee_items for each row execute function public.block_closed_term();
create trigger payments_closed_term before insert or update on public.payments for each row execute function public.block_closed_term();

create function public.term_close_check(p_term uuid)
returns jsonb
language plpgsql stable security invoker as $$
declare
  v_term public.terms%rowtype;
  v_weeks jsonb;
  v_scores jsonb;
  v_staff integer;
begin
  select * into v_term from public.terms where id = p_term;
  if not found then
    raise exception 'Term not found';
  end if;

  -- a week is due once its Friday is inside the term and has passed (rule A6)
  select coalesce(jsonb_agg(jsonb_build_object('class_id', x.class_id, 'class_name', x.class_name, 'weeks', x.weeks) order by x.level_order), '[]'::jsonb) into v_weeks
    from (
      select c.id as class_id, c.name as class_name, c.level_order, jsonb_agg(m.monday order by m.monday) as weeks
        from public.classes c
        cross join lateral (
          select d::date as monday
            from generate_series(date_trunc('week', v_term.start_date)::date, v_term.end_date, interval '7 days') d
           where d::date + 4 <= v_term.end_date and d::date + 4 <= current_date
        ) m
       where exists (select 1 from public.students s where s.class_id = c.id and s.status = 'active')
         and not exists (select 1 from public.attendance_weeks w where w.class_id = c.id and w.week_start = m.monday)
       group by c.id, c.name, c.level_order
    ) x;

  select coalesce(jsonb_agg(jsonb_build_object('class_id', x.class_id, 'class_name', x.class_name, 'students', x.students, 'incomplete', x.incomplete) order by x.level_order), '[]'::jsonb) into v_scores
    from (
      select c.id as class_id, c.name as class_name, c.level_order, count(*) as students,
             count(*) filter (where r.subjects_expected = 0 or r.subjects_scored < r.subjects_expected) as incomplete
        from public.results_summary(p_term) r join public.classes c on c.id = r.class_id
       group by c.id, c.name, c.level_order
      having count(*) filter (where r.subjects_expected = 0 or r.subjects_scored < r.subjects_expected) > 0
    ) x;

  select count(*) into v_staff
    from generate_series(v_term.start_date, least(v_term.end_date, current_date), interval '1 day') d
   where extract(isodow from d) < 6
     and exists (select 1 from public.staff where status = 'active')
     and not exists (select 1 from public.non_school_days n where n.non_school_date = d::date)
     and not exists (select 1 from public.staff_attendance a where a.attendance_date = d::date);

  return jsonb_build_object('weeks_missing', v_weeks, 'scores_missing', v_scores, 'staff_days_missing', v_staff);
end $$;

create function public.close_term(p_term uuid, p_accept_gaps boolean default false)
returns void
language plpgsql security invoker as $$
declare
  v_term public.terms%rowtype;
  v_check jsonb;
  v_year text;
  v_snapshot jsonb;
  v_rows integer;
begin
  if public.app_role() is distinct from 'admin' then
    raise exception 'Only the Admin can close a term';
  end if;
  select * into v_term from public.terms where id = p_term;
  if not found then
    raise exception 'Term not found';
  end if;
  if v_term.status = 'closed' then
    raise exception 'This term is already closed';
  end if;
  v_check := public.term_close_check(p_term);
  if not p_accept_gaps and (jsonb_array_length(v_check -> 'weeks_missing') > 0 or jsonb_array_length(v_check -> 'scores_missing') > 0 or (v_check ->> 'staff_days_missing')::int > 0) then
    raise exception 'There are gaps in the records. Fix them, or close anyway to accept them';
  end if;
  select name into v_year from public.academic_years where id = v_term.academic_year_id;

  v_snapshot := jsonb_build_object(
    'term', jsonb_build_object('id', v_term.id, 'name', v_term.name, 'year', v_year, 'start_date', v_term.start_date, 'end_date', v_term.end_date),
    'check', v_check,
    'classes', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name) order by c.level_order), '[]'::jsonb) from public.classes c),
    'students', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'full_name', s.full_name, 'admission_no', s.admission_no, 'gender', s.gender, 'class_id', s.class_id) order by s.full_name), '[]'::jsonb) from public.students s where s.status = 'active'),
    'attendance', (select coalesce(jsonb_agg(to_jsonb(a)), '[]'::jsonb) from public.attendance_term_totals(p_term) a),
    'staff', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'full_name', f.full_name)), '[]'::jsonb) from public.staff f),
    'staff_attendance', (select coalesce(jsonb_agg(to_jsonb(a)), '[]'::jsonb) from public.staff_attendance_totals(p_term) a),
    'results', (select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb) from public.results_summary(p_term) r),
    'fees', (select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb) from public.fee_balances(p_term) b),
    'turnover', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.enrolment_turnover(p_term) t),
    'turnover_students', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.turnover_students(p_term) t)
  );

  insert into public.term_snapshots (term_id, data) values (p_term, v_snapshot);
  update public.terms set status = 'closed' where id = p_term;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'Only the Admin can close a term';
  end if;
end $$;

create function public.reopen_term(p_term uuid, p_reason text)
returns void
language plpgsql security invoker as $$
declare
  v_term public.terms%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_rows integer;
begin
  if public.app_role() is distinct from 'admin' then
    raise exception 'Only the Admin can reopen a term';
  end if;
  if length(v_reason) < 3 then
    raise exception 'Give the reason for reopening this term';
  end if;
  if length(v_reason) > 300 then
    raise exception 'The reason can have at most 300 characters';
  end if;
  select * into v_term from public.terms where id = p_term;
  if not found then
    raise exception 'Term not found';
  end if;
  if v_term.status <> 'closed' then
    raise exception 'This term is not closed';
  end if;
  if exists (select 1 from public.terms t where t.status = 'closed' and t.start_date > v_term.start_date) then
    raise exception 'A later term is closed. Reopen that one first';
  end if;
  update public.term_snapshots set reopened_reason = v_reason
   where id = (select s.id from public.term_snapshots s where s.term_id = p_term order by s.closed_at desc limit 1);
  update public.terms set status = 'open' where id = p_term;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception 'Only the Admin can reopen a term';
  end if;
end $$;

grant execute on function public.term_close_check(uuid) to authenticated;
grant execute on function public.close_term(uuid, boolean) to authenticated;
grant execute on function public.reopen_term(uuid, text) to authenticated;

-- ======================================================================
-- 20261118002800_year_end_promotion.sql
-- ======================================================================
-- T27: year-end promotion (rule S7). Admin only.
-- Moves every active student up to the next class (by class order), keeps repeaters in their class, and graduates
-- students in the last class (JHS 3). Every change is a dated movement in the student's history (rule S2), so
-- nothing is lost: graduates keep their record and history.
--
-- Because students now change class, "which class was this student in at that time?" matters for old fees.
-- student_class_on answers it from the movement history, and fee_balances and parent_fees now use it, so arrears
-- from an earlier term are worked out from the fees of the class the student was really in then.

create function public.student_class_on(p_student uuid, p_date date)
returns uuid
language sql stable as $$
  -- The class of the latest move on or before the date. If the student was entered into the system after that
  -- date (for example existing pupils added later), use the first class they were recorded in.
  select coalesce(
    (select m.to_class_id from public.student_movements m
      where m.student_id = p_student and m.to_class_id is not null and m.moved_on <= p_date
      order by m.moved_on desc, m.created_at desc limit 1),
    (select m.to_class_id from public.student_movements m
      where m.student_id = p_student and m.to_class_id is not null
      order by m.moved_on asc, m.created_at asc limit 1),
    (select s.class_id from public.students s where s.id = p_student)
  )
$$;

create or replace function public.fee_balances(p_term uuid, p_class uuid default null)
returns table (student_id uuid, admission_no text, full_name text, class_id uuid, owed numeric, paid numeric, balance numeric, arrears numeric)
language sql stable security invoker as $$
  with this_term as (select start_date from public.terms where id = p_term),
  fees as (select fi.class_id, fi.term_id, sum(fi.amount) as total from public.fee_items fi group by fi.class_id, fi.term_id),
  pay as (select py.student_id, py.term_id, sum(py.amount) as total from public.payments py where py.status = 'valid' group by py.student_id, py.term_id)
  select s.id, s.admission_no, s.full_name, s.class_id,
         coalesce(f.total, 0), coalesce(p.total, 0), coalesce(f.total, 0) - coalesce(p.total, 0),
         coalesce((
           select sum(
                    coalesce((select sum(fi.amount) from public.fee_items fi
                               where fi.term_id = t2.id and fi.class_id = public.student_class_on(s.id, t2.end_date)), 0)
                    - coalesce(p2.total, 0))
             from public.terms t2
             left join pay p2 on p2.student_id = s.id and p2.term_id = t2.id
            where t2.start_date < (select start_date from this_term)
         ), 0)
    from public.students s
    left join fees f on f.class_id = s.class_id and f.term_id = p_term
    left join pay p on p.student_id = s.id and p.term_id = p_term
   where s.status = 'active' and (p_class is null or s.class_id = p_class)
   order by s.full_name
$$;

create or replace function public.parent_fees()
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_student public.students%rowtype;
  v_terms jsonb;
  v_pay jsonb;
begin
  select * into v_student from public.students where id = public.parent_child_id();
  if not found then
    raise exception 'Not available';
  end if;
  select coalesce(jsonb_agg(q.j order by q.start_date desc), '[]'::jsonb) into v_terms
    from (
      select t.start_date, jsonb_build_object('term_id', t.id, 'term_name', t.name, 'year_name', y.name,
               'owed', coalesce(f.total, 0), 'paid', coalesce(p.total, 0), 'balance', coalesce(f.total, 0) - coalesce(p.total, 0)) as j
        from public.terms t
        join public.academic_years y on y.id = t.academic_year_id
        left join lateral (
          select sum(fi.amount) as total from public.fee_items fi
           where fi.term_id = t.id and fi.class_id = public.student_class_on(v_student.id, least(t.end_date, current_date))
        ) f on true
        left join (select term_id, sum(amount) as total from public.payments where student_id = v_student.id and status = 'valid' group by term_id) p on p.term_id = t.id
       where t.start_date <= current_date and (f.total is not null or p.total is not null)
    ) q;
  select coalesce(jsonb_agg(jsonb_build_object('receipt_no', py.receipt_no, 'amount', py.amount, 'paid_on', py.paid_on, 'term_name', t.name) order by py.paid_on desc, py.receipt_no desc), '[]'::jsonb) into v_pay
    from public.payments py join public.terms t on t.id = py.term_id
   where py.student_id = v_student.id and py.status = 'valid';
  return jsonb_build_object('terms', v_terms, 'payments', v_pay);
end $$;

create function public.promote_year(p_year uuid, p_repeaters uuid[], p_moved_on date)
returns table (promoted integer, repeated integer, graduated integer)
language plpgsql security invoker as $$
declare
  v_last public.terms%rowtype;
  r record;
  v_next uuid;
  v_promoted integer := 0;
  v_repeated integer := 0;
  v_graduated integer := 0;
begin
  if public.app_role() is distinct from 'admin' then
    raise exception 'Only the Admin can promote students';
  end if;
  select * into v_last from public.terms where academic_year_id = p_year order by start_date desc limit 1;
  if not found then
    raise exception 'This academic year has no terms';
  end if;
  if exists (select 1 from public.terms t where t.academic_year_id = p_year and t.status <> 'closed') then
    raise exception 'Close every term of this year first';
  end if;
  if p_moved_on is null or p_moved_on <= v_last.end_date then
    raise exception 'The promotion date must be after the last term of the year ends';
  end if;
  if p_moved_on > current_date then
    raise exception 'The date cannot be in the future';
  end if;
  if exists (select 1 from public.student_movements m where m.term_id = v_last.id and m.movement in ('promoted', 'repeated')) then
    raise exception 'Promotion has already been done for this year';
  end if;

  for r in
    select s.id, s.class_id, c.level_order
      from public.students s join public.classes c on c.id = s.class_id
     where s.status = 'active'
     order by s.full_name
  loop
    select c2.id into v_next from public.classes c2 where c2.level_order > r.level_order order by c2.level_order limit 1;
    if r.id = any (coalesce(p_repeaters, '{}')) then
      insert into public.student_movements (student_id, term_id, movement, moved_on, reason, from_class_id, to_class_id)
      values (r.id, v_last.id, 'repeated', p_moved_on, 'Repeats the class', r.class_id, r.class_id);
      v_repeated := v_repeated + 1;
    elsif v_next is null then
      update public.students set status = 'graduated' where id = r.id;
      insert into public.student_movements (student_id, term_id, movement, moved_on, reason, from_class_id)
      values (r.id, v_last.id, 'graduated', p_moved_on, 'Completed the last class', r.class_id);
      v_graduated := v_graduated + 1;
    else
      update public.students set class_id = v_next where id = r.id;
      insert into public.student_movements (student_id, term_id, movement, moved_on, reason, from_class_id, to_class_id)
      values (r.id, v_last.id, 'promoted', p_moved_on, 'Promoted at the end of the year', r.class_id, v_next);
      v_promoted := v_promoted + 1;
    end if;
  end loop;

  return query select v_promoted, v_repeated, v_graduated;
end $$;

grant execute on function public.student_class_on(uuid, date) to authenticated;
grant execute on function public.promote_year(uuid, uuid[], date) to authenticated;

-- ======================================================================
-- 20261118002900_single_score.sql
-- ======================================================================
-- Scores are now entered as ONE mark out of 100 per subject (no 30/70 split).
-- The mark is stored in exam_score and class_score is stored as 0, so totals, grades, positions, report cards,
-- parent views and summaries keep working unchanged (total = class_score + exam_score).
-- Older rows that were entered as class + exam still add up to the same total and show as one mark.
update public.settings set exam_score_max = 100;
alter table public.settings alter column exam_score_max set default 100;

-- Rule G6 now: one mark cannot be above the maximum (100 unless changed in settings).
create or replace function public.check_score_limits() returns trigger
language plpgsql as $$
declare
  v_class_max numeric;
  v_exam_max numeric;
begin
  select class_score_max, exam_score_max into v_class_max, v_exam_max from public.settings limit 1;
  v_class_max := coalesce(v_class_max, 100);
  v_exam_max := coalesce(v_exam_max, 100);
  if new.class_score > v_class_max or new.exam_score > v_exam_max then
    raise exception 'The score cannot be more than %', v_exam_max;
  end if;
  return new;
end $$;

-- ======================================================================
-- 20261118003000_notices.sql
-- ======================================================================
-- T30: notices. Admin and Staff post a notice for staff; the poster can also tick "show to parents".
-- Admin can edit or hide (archive) a notice. Notices are never deleted. Parents have no table access: they read
-- only notices marked for parents, through one narrow function.

create table public.notices (
  id uuid primary key default gen_random_uuid(),
  title text not null check (char_length(btrim(title)) between 1 and 120),
  body text not null check (char_length(btrim(body)) between 1 and 2000),
  audience text not null default 'staff' check (audience in ('staff', 'staff_and_parents')),
  archived boolean not null default false,
  posted_by_name text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);
create index notices_created_idx on public.notices (created_at desc);

-- Remember who posted it by name, so the list does not need to read the profiles table.
create function public.notices_set_poster() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.posted_by_name := (select full_name from public.profiles where auth_user_id = auth.uid());
  return new;
end $$;
create trigger notices_poster before insert on public.notices
  for each row execute function public.notices_set_poster();

alter table public.notices enable row level security;
create policy notices_read on public.notices for select to authenticated
  using (public.app_role() in ('admin', 'staff'));
create policy notices_insert on public.notices for insert to authenticated
  with check (public.app_role() in ('admin', 'staff') and not archived);
create policy notices_admin_update on public.notices for update to authenticated
  using (public.app_role() = 'admin') with check (public.app_role() = 'admin');

create trigger notices_history after update on public.notices
  for each row execute function public.log_history();
create trigger notices_no_delete before delete on public.notices
  for each row execute function public.block_delete();

-- What a parent sees: notices marked for parents, newest first.
create function public.parent_notices()
returns table (id uuid, title text, body text, created_at timestamptz, posted_by_name text)
language plpgsql stable security definer set search_path = public as $$
begin
  if public.parent_child_id() is null then
    raise exception 'Not available';
  end if;
  return query
    select n.id, n.title, n.body, n.created_at, n.posted_by_name
      from public.notices n
     where n.audience = 'staff_and_parents' and not n.archived
     order by n.created_at desc
     limit 30;
end $$;
revoke execute on function public.parent_notices() from public;
grant execute on function public.parent_notices() to authenticated;

-- ======================================================================
-- 20261118003100_timetable.sql
-- ======================================================================
-- T31: the timetable is one document (PDF, picture or Word file) uploaded by the Admin for a whole term.
-- Admin and Staff can open it. Parents cannot (not asked for). Nothing is deleted: uploading a new file for a term
-- hides the older one, and the older file stays in storage.

create table public.timetables (
  id uuid primary key default gen_random_uuid(),
  term_id uuid not null references public.terms (id),
  file_path text not null unique,
  file_name text not null check (char_length(btrim(file_name)) between 1 and 200),
  content_type text,
  size_bytes bigint check (size_bytes is null or size_bytes between 1 and 10485760),
  archived boolean not null default false,
  uploaded_by_name text,
  created_by uuid references auth.users default auth.uid(),
  created_at timestamptz not null default now()
);
create index timetables_term_idx on public.timetables (term_id, created_at desc);

create function public.timetables_set_uploader() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.uploaded_by_name := (select full_name from public.profiles where auth_user_id = auth.uid());
  return new;
end $$;
create trigger timetables_uploader before insert on public.timetables
  for each row execute function public.timetables_set_uploader();

alter table public.timetables enable row level security;
create policy timetables_read on public.timetables for select to authenticated
  using (public.app_role() in ('admin', 'staff'));
create policy timetables_admin_write on public.timetables for all to authenticated
  using (public.app_role() = 'admin') with check (public.app_role() = 'admin');

create trigger timetables_history after update on public.timetables
  for each row execute function public.log_history();
create trigger timetables_no_delete before delete on public.timetables
  for each row execute function public.block_delete();

-- The private file store (Supabase Storage). Skipped where Storage does not exist (the test database).
-- Only the Admin can add files; Admin and Staff can read them; nobody can change or delete a stored file.
do $$
begin
  if to_regclass('storage.objects') is not null then
    insert into storage.buckets (id, name, public, file_size_limit)
    values ('timetables', 'timetables', false, 10485760)
    on conflict (id) do nothing;
    execute $p$create policy timetable_files_read on storage.objects for select to authenticated
      using (bucket_id = 'timetables' and public.app_role() in ('admin', 'staff'))$p$;
    execute $p$create policy timetable_files_add on storage.objects for insert to authenticated
      with check (bucket_id = 'timetables' and public.app_role() = 'admin')$p$;
  end if;
end $$;

-- ======================================================================
-- 20261118003200_lock_function_access.sql
-- ======================================================================
-- Security hardening. Supabase lets the "anon" role (anyone holding the public site key, without logging in)
-- run every function in the public schema by default. "revoke ... from public" in earlier migrations does not
-- remove that. Row-level security already stops anon from reading or changing data, but nobody who is not
-- logged in should be able to call these functions at all, so we take the permission away explicitly.
revoke execute on all functions in schema public from public, anon;
alter default privileges in schema public revoke execute on functions from public, anon;
